import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const m=JSON.parse('{"title":"Capability workers and durable jobs","description":"","frontmatter":{},"headers":[],"relativePath":"project/plugins.md","filePath":"project/plugins.md","lastUpdated":1794374806000}'),n={name:"project/plugins.md"};function s(o,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="capability-workers-and-durable-jobs" tabindex="-1">Capability workers and durable jobs <a class="header-anchor" href="#capability-workers-and-durable-jobs" aria-label="Permalink to &quot;Capability workers and durable jobs&quot;">​</a></h1><p><strong>Proposed contracts.</strong> Existing Ordo executor behavior is a donor, not evidence that native plugins are already implemented here.</p><h2 id="capability-versus-implementation" tabindex="-1">Capability versus implementation <a class="header-anchor" href="#capability-versus-implementation" aria-label="Permalink to &quot;Capability versus implementation&quot;">​</a></h2><p>A workflow requests a versioned capability, not an Apple class or CUDA library. CPU, NVIDIA and native Mac workers can implement that capability with declared model and resource requirements. Compatible interface shape does not guarantee equal inference quality or embedding compatibility.</p><p>Rust owns coordination and state. Swift is useful for Apple-native frameworks; such a worker is not expected to execute unchanged on Linux. Keep the application usable without a GPU through deterministic fixtures, structured imports, manual review and available retrieval paths.</p><h2 id="one-result-contract" tabindex="-1">One result contract <a class="header-anchor" href="#one-result-contract" aria-label="Permalink to &quot;One result contract&quot;">​</a></h2><p>Reconcile the historical Rust envelope, current TypeScript envelope and private executor envelope before importing any of them. They currently differ in statuses, identity and output shape. The target contract needs these fields:</p><table tabindex="0"><thead><tr><th>Group</th><th>Required information</th></tr></thead><tbody><tr><td>Version/identity</td><td>Schema, capability/backend, job/task, worker, attempt/lease epoch</td></tr><tr><td>Inputs</td><td>Immutable artifact IDs/hashes, parameter/model fingerprints and scope</td></tr><tr><td>Execution</td><td>Deadline, cancellation, bounded resources, tool/model versions and outcome</td></tr><tr><td>Outputs</td><td>Byte-verified artifacts, typed source locations, evidence links and limitations</td></tr><tr><td>Acceptance</td><td>Authenticated worker identity, current lease, allowed outputs and idempotency receipt</td></tr></tbody></table><p>Do not fill a missing byte digest from an artifact label. Failed/blocked outcomes may have diagnostics without successful output evidence; successful evidence-producing capabilities must meet their explicit evidence contract. A worker cannot grant itself permission by setting a field in its result.</p><h2 id="state-and-transport-boundary" tabindex="-1">State and transport boundary <a class="header-anchor" href="#state-and-transport-boundary" aria-label="Permalink to &quot;State and transport boundary&quot;">​</a></h2><p>Workers never write canonical tables. In the hosted profile they call the private Rust store&#39;s scoped acceptance command; in local mode the same contract may use an embedded adapter. The store checks the receipt and commits state/events in one transaction.</p><p>Review the existing HTTP/JSON host-worker proposal before choosing a different serialization transport. Language-neutral contracts matter more than Protobuf versus JSON. Do not expose Rust&#39;s native trait-object ABI as a stable public plugin interface. <a href="https://doc.rust-lang.org/reference/items/external-blocks.html" target="_blank" rel="noreferrer">Rust ABI reference</a>.</p><p>Native process isolation is not a sandbox by itself. Define permitted directories/artifact handles, device access, network egress, executable identity and cancellation limits. Remote worker attachment requires explicit authorization; it is not an arbitrary public command runner.</p><h2 id="durable-task-state" tabindex="-1">Durable task state <a class="header-anchor" href="#durable-task-state" aria-label="Permalink to &quot;Durable task state&quot;">​</a></h2><p>Plans are versioned snapshots. Validate dependency cycles, missing keys and required stages before creating a job. Human review is durable waiting state, not a worker holding an open transaction.</p><p>Claims carry an epoch and deadline. Completion checks job, task, worker, epoch, expiry, input digest and expected status atomically. Retry classes distinguish safe deterministic processing from paid generation with partial output. A stale result cannot regain authority just because its worker name matches a newer attempt.</p><p>Bound queue depth, attempts, concurrency, output size and temporary storage. Use heartbeats and explicit blocked/dead-letter inspection. Preserve diagnostic failure events without converting corrupt evidence into an empty successful result. Historical kernel/event symbols and their missing tests are mapped in the <a href="./../reuse/source-audit">audit</a>.</p><h2 id="readiness-and-large-media" tabindex="-1">Readiness and large media <a class="header-anchor" href="#readiness-and-large-media" aria-label="Permalink to &quot;Readiness and large media&quot;">​</a></h2><p>Report missing tool/model, unsupported host, unbound source, missing credential, policy block and user disablement separately. No compatible encoder means no compatible semantic query—not permission to silently switch vector spaces.</p><p>Control messages refer to durable artifacts; large media uses files or negotiated local buffers. GPU handles and shared memory are ephemeral execution details. Future video runs use bounded segments, source hashes and explicit timestamps. Record sampling/skipped intervals, and pause or spool within quotas under overload. Never claim full analysis of intervals that were dropped.</p><p>See the <a href="./../engineering/examples#lease-ownership">lease lab</a>, <a href="./../engineering/twelve-factor">factor gates</a> and S1/S6 in the <a href="./roadmap">roadmap</a>.</p>',21)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
